#include "codec.hpp"
#include <algorithm>
#include <cstring>
#include <limits>
namespace codec {
uint32_t read32(const uint8_t* p) {return uint32_t(p[0]) | uint32_t(p[1])<<8 | uint32_t(p[2])<<16 | uint32_t(p[3])<<24;}
uint64_t read64(const uint8_t* p) {return read32(p) | uint64_t(read32(p+4))<<32;}
void put32(Bytes& o,uint32_t x) { for(int k=0;k<4;++k) o.push_back(uint8_t(x>>(k*8))); }
void put64(Bytes& o,uint64_t x) { for(int k=0;k<8;++k) o.push_back(uint8_t(x>>(k*8))); }
static uint32_t rot(uint32_t x,int n) {return (x<<n)|(x>>(32-n));}
uint32_t checksum(const uint8_t* p, size_t n, uint32_t seed) {
    constexpr uint32_t A=2654435761u,B=2246822519u,C=3266489917u,D=668265263u,E=374761393u;
    size_t i=0;uint32_t h;
    if(n>=16) {
        uint32_t v[4]={seed+A+B,seed+B,seed,seed-A};
        do {for(int j=0;j<4;++j) {v[j]=rot(v[j]+read32(p+i)*B,13)*A;i+=4;}} while(i+16<=n);
        h=rot(v[0],1)+rot(v[1],7)+rot(v[2],12)+rot(v[3],18);
    } else h=seed+E;
    h+=uint32_t(n);
    while(i+4<=n) {h=rot(h+read32(p+i)*C,17)*D;i+=4;}
    while(i<n) h=rot(h+uint32_t(p[i++])*E,11)*A;
    h^=h>>15;h*=B;h^=h>>13;h*=C;h^=h>>16;return h;
}
static void extra(Bytes& out, size_t len) {while(len>=255){out.push_back(255);len-=255;}out.push_back(uint8_t(len));}
static void sequence(Bytes& out,const Bytes& data,size_t anchor,size_t pos,size_t offset,size_t length) {
    size_t lit=pos-anchor,ml=length-4;
    out.push_back(uint8_t((std::min(lit,size_t(15))<<4)|std::min(ml,size_t(15))));
    if(lit>=15)extra(out,lit-15);
    out.insert(out.end(),data.begin()+anchor,data.begin()+pos);
    out.push_back(uint8_t(offset));out.push_back(uint8_t(offset>>8));
    if(ml>=15)extra(out,ml-15);
}
static void lastLiterals(Bytes& out,const Bytes& data,size_t anchor) {
    size_t n=data.size()-anchor;
    out.push_back(uint8_t(std::min(n,size_t(15))<<4));
    if(n>=15)extra(out,n-15);
    out.insert(out.end(),data.begin()+anchor,data.end());
}
Bytes fastBlock(const Bytes& input,int accel,const Bytes& dict) {
    Bytes data;
    size_t ds=std::min(size_t(65536),dict.size());
    if(ds<4)ds=0;
    data.reserve(ds+input.size());
    data.insert(data.end(),dict.end()-ds,dict.end());
    data.insert(data.end(),input.begin(),input.end());
    const size_t n=data.size(),start=ds;
    Bytes out;out.reserve(input.size()+input.size()/255+16);
    bool small=ds==0 && input.size()<65547;
    const int bits=small?13:12;
    std::vector<int> table(1<<bits,ds? -1:0);
    auto hash=[&](size_t p)->unsigned {
        if(small) return (read32(data.data()+p)*2654435761u)>>(32-bits);
        return unsigned(((read64(data.data()+p)<<24)*uint64_t(889523592379ull))>>(64-bits));
    };
    if(ds) for(size_t i=0;i+8<=ds;i+=3)table[hash(i)]=int(i);
    size_t anchor=start, pos=start;
    accel=std::max(1,std::min(accel,65537));
    if(input.size()<13){lastLiterals(out,data,anchor);return out;}
    if(!ds) {table[hash(pos)]=int(pos);++pos;}
    while(true) {
        size_t forward=pos, step=1, attempts=size_t(accel)<<6;
        int match=-1;
        bool found=false;
        while(true) {
            pos=forward;forward+=step;step=attempts++>>6;
            if(forward>n-11)break;
            unsigned h=hash(pos);match=table[h];table[h]=int(pos);
            if(match>=0 && size_t(match)<pos && pos-size_t(match)<=65535 && read32(data.data()+match)==read32(data.data()+pos)) {found=true;break;}
        }
        if(!found)break;
        while(pos>anchor && match>0 && data[pos-1]==data[match-1]){--pos;--match;}
        while(true) {
            size_t len=4;
            while(pos+len<n-5 && data[pos+len]==data[size_t(match)+len])++len;
            sequence(out,data,anchor,pos,pos-size_t(match),len);
            pos+=len;anchor=pos;
            if(pos>n-12) {lastLiterals(out,data,anchor);return out;}
            table[hash(pos-2)]=int(pos-2);
            unsigned h=hash(pos);match=table[h];table[h]=int(pos);
            if(match>=0 && size_t(match)<pos && pos-size_t(match)<=65535 && read32(data.data()+match)==read32(data.data()+pos)) continue;
            ++pos;break;
        }
    }
    lastLiterals(out,data,anchor);return out;
}
Bytes highBlock(const Bytes& data,int level,bool favor,const Bytes& dict) {
    // The high-ratio parser is filled in separately from the fast parser.
    (void)level;(void)favor;
    return fastBlock(data,1,dict);
}
Bytes expandBlock(const uint8_t* p,size_t n,size_t maximum,const Bytes& dict) {
    Bytes out;out.reserve(std::min(maximum,n*4));size_t i=0;
    auto bad=[](){throw Error(34,"Decompression error : ERROR_decompressionFailed");};
    auto length=[&](size_t l)->size_t {if(l==15){uint8_t c;do {if(i>=n)bad();c=p[i++];l+=c;if(l>maximum)bad();}while(c==255);}return l;};
    while(i<n){
        uint8_t t=p[i++];size_t literals=length(t>>4);
        if(i+literals>n || out.size()+literals>maximum)bad();
        out.insert(out.end(),p+i,p+i+literals);i+=literals;
        if(i==n) return out;
        if(i+2>n)bad();
        size_t off=p[i]|size_t(p[i+1])<<8;i+=2;
        size_t len=length(t&15)+4;
        if(off==0 || off>out.size()+dict.size() || out.size()+len>maximum || n-i<6)bad();
        for(size_t j=0;j<len;++j){
            if(off>out.size())out.push_back(dict[dict.size()-(off-out.size())]);
            else out.push_back(out[out.size()-off]);
        }
    }
    bad();return {};
}
Bytes compress(const Bytes& data,const Settings& cfg,const Bytes& dict) {
    Bytes result;
    if(cfg.legacy) {
        put32(result,0x184c2102);
        for(size_t p=0;p<data.size();p+=8*1024*1024) {
            Bytes block(data.begin()+p,data.begin()+std::min(data.size(),p+8*1024*1024));
            Bytes compressed=cfg.level<3 ? fastBlock(block,cfg.acceleration) : highBlock(block,cfg.level,cfg.favorSpeed);
            put32(result,uint32_t(compressed.size()));result.insert(result.end(),compressed.begin(),compressed.end());
        }
        return result;
    }
    int bid=cfg.blockId;
    if(data.size()<4*1024*1024)while(bid>4 && data.size()<=(size_t(1)<<(8+2*(bid-1))))--bid;
    size_t blockSize=size_t(1)<<(8+2*bid);
    bool linked=cfg.linked && (data.size()>=4*1024*1024 || data.size()>blockSize);
    bool content=cfg.contentSize&&!data.empty();
    put32(result,0x184d2204);
    result.push_back(uint8_t(0x40|(!linked?0x20:0)|(cfg.blockCrc?0x10:0)|(content?8:0)|(cfg.frameCrc?4:0)));
    result.push_back(uint8_t(bid<<4));
    if(content)put64(result,uint64_t(data.size()));
    result.push_back(uint8_t(checksum(result.data()+4,result.size()-4)>>8));
    Bytes history=dict;
    for(size_t p=0;p<data.size();p+=blockSize) {
        Bytes block(data.begin()+p,data.begin()+std::min(p+blockSize,data.size()));
        Bytes packed=cfg.level<3 ? fastBlock(block,cfg.acceleration,history) : highBlock(block,cfg.level,cfg.favorSpeed,history);
        bool raw=packed.size()>=block.size();const Bytes& src=raw?block:packed;
        put32(result,uint32_t(src.size())|(raw?0x80000000u:0));
        result.insert(result.end(),src.begin(),src.end());
        if(cfg.blockCrc)put32(result,checksum(src));
        if(linked){history.insert(history.end(),block.begin(),block.end());if(history.size()>65536)history.erase(history.begin(),history.end()-65536);}
    }
    put32(result,0);if(cfg.frameCrc)put32(result,checksum(data));return result;
}
Frame header(const Bytes& data,size_t& pos) {
    Frame f;f.start=pos;
    if(pos+7>data.size())throw Error(26,"LZ4F frame decoding could not complete: invalid frame");
    if(read32(data.data()+pos)!=0x184d2204)throw Error(34,"Decompression error : ERROR_frameType_unknown");
    uint8_t flags=data[pos+4],bd=data[pos+5];
    if((flags>>6)!=1)throw Error(34,"Decompression error : ERROR_headerVersion_wrong");
    if((flags&2)||(bd&0x8f))throw Error(34,"Decompression error : ERROR_reservedFlag_set");
    f.blockId=(bd>>4)&7;
    if(f.blockId<4 || f.blockId>7)throw Error(34,"Decompression error : ERROR_maxBlockSize_invalid");
    f.independent=flags&32;f.blockCrc=flags&16;f.contentCrc=flags&4;
    size_t len=7+((flags&8)?8:0)+((flags&1)?4:0);
    if(pos+len>data.size())throw Error(26,"LZ4F frame decoding could not complete: invalid frame");
    if((checksum(data.data()+pos+4,len-5)>>8 &255)!=data[pos+len-1])throw Error(34,"Decompression error : ERROR_headerChecksum_invalid");
    if(flags&8)f.contentSize=read64(data.data()+pos+6);
    pos+=len;return f;
}
DecodeResult decompress(const Bytes& data,const Bytes& dict,bool pass,bool seekable) {
    DecodeResult ret;size_t p=0;bool first=true;
    try {
        while(p<data.size()) {
            if(data.size()-p<4)throw Error(first?40:26,first?"Unrecognized header : Magic Number unreadable":"LZ4F frame decoding could not complete: invalid frame");
            uint32_t magic=read32(data.data()+p);
            if((magic&0xfffffff0u)==0x184d2a50u) {
                if(p+8>data.size())throw Error(42,"Stream error : skippable size unreadable");
                size_t size=read32(data.data()+p+4);p+=8;
                if(size>data.size()-p && !seekable)throw Error(43,"Stream error : cannot skip skippable area");
                p+=size;first=false;continue;
            }
            if(magic==0x184c2102) {
                p+=4;first=false;
                while(p<data.size()){
                    if(p+4>data.size())throw Error(51,"Read error : cannot access block size");
                    uint32_t size=read32(data.data()+p);
                    if(size>8*1024*1024+8*1024*1024/255+16)break;
                    p+=4;
                    if(p+size>data.size())throw Error(52,"Read error : cannot access compressed block !");
                    Bytes b;
                    try{b=expandBlock(data.data()+p,size,8*1024*1024);}catch(const Error&){throw Error(53,"Decoding Failed ! Corrupted input detected !");}
                    ret.data.insert(ret.data.end(),b.begin(),b.end());ret.hadData=true;p+=size;
                }
                continue;
            }
            if(magic!=0x184d2204 && first){
                if(pass){ret.data=data;return ret;}
                throw Error(44,"Unrecognized header : file cannot be decoded");
            }
            Frame f=header(data,p);Bytes frame;Bytes history=dict;
            bool complete=false;
            while(p+4<=data.size()) {
                uint32_t field=read32(data.data()+p);p+=4;
                if(field==0){complete=true;break;}
                size_t len=field&0x7fffffffu;
                if(len>(size_t(1)<<(8+f.blockId*2)))throw Error(34,"Decompression error : ERROR_maxBlockSize_invalid");
                if(p+len+(f.blockCrc?4:0)>data.size())break;
                if(f.blockCrc && checksum(data.data()+p,len)!=read32(data.data()+p+len))throw Error(34,"Decompression error : ERROR_blockChecksum_invalid");
                Bytes block;
                if(field&0x80000000u)block.assign(data.begin()+p,data.begin()+p+len);
                else block=expandBlock(data.data()+p,len,size_t(1)<<(8+f.blockId*2),history);
                frame.insert(frame.end(),block.begin(),block.end());
                if(!f.independent){history.insert(history.end(),block.begin(),block.end());if(history.size()>65536)history.erase(history.begin(),history.end()-65536);}
                p+=len+(f.blockCrc?4:0);
            }
            if(!complete || (f.contentCrc && p+4>data.size())) {
                if(p==data.size() || data.size()-p==3){ret.data.insert(ret.data.end(),frame.begin(),frame.end());ret.hadData=!frame.empty();}
                throw Error(26,"LZ4F frame decoding could not complete: invalid frame");
            }
            if(f.contentSize && f.contentSize!=frame.size())throw Error(34,"Decompression error : ERROR_frameSize_wrong");
            if(f.contentCrc){if(checksum(frame)!=read32(data.data()+p))throw Error(34,"Decompression error : ERROR_contentChecksum_invalid");p+=4;}
            ret.data.insert(ret.data.end(),frame.begin(),frame.end());ret.hadData=true;first=false;
        }
    } catch(const Error& e){ret.error=e.code;ret.message=e.what();}
    return ret;
}
}
