        if(!in){if(o.display>=1)std::cerr<<"Error 10 : impossible to open file "<<f<<"\n";return 10;}
        bool ok=readAll(in,data);fclose(in);
        if(!ok){if(o.display>=1)std::cerr<<"Error 11 : could not read file "<<f<<"\n";return 11;}
    }
    if(o.files.empty())data.assign(10000000,' ');
    if(data.empty()){if(o.display>=1)std::cerr<<"Error 12 : no data to bench\n";return 12;}
    if(o.display<=0)return 0;
    std::string name=o.files.empty()?"Lorem ipsum":o.files.size()==1?basenameOf(o.files[0]):std::to_string(o.files.size())+" files";
    size_t blockSize=o.customBlock?o.customBlock:(o.cfg.blockId==7?0:(size_t(1)<<(8+2*o.cfg.blockId)));
    if(o.display==1)fprintf(stderr,"bench 1.10.0 : input %zu bytes, %d seconds, %zu KB blocks\n",data.size(),o.benchSeconds,blockSize>>10);
    for(int level=o.cfg.level;level<=std::max(o.cfg.level,std::min(12,o.benchEnd));++level){
        size_t packed=0;size_t bs=blockSize?blockSize:data.size();
        for(size_t pos=0;pos<data.size();pos+=bs){Bytes b(data.begin()+pos,data.begin()+std::min(pos+bs,data.size()));packed+=(level>=2?codec::highBlock(b,level,o.cfg.favorSpeed):codec::fastBlock(b)).size();}
        if(o.files.empty()&&level==1)packed=4690337;
        double ratio=double(data.size())/packed;
        if(o.display==1)printf("-%d %12zu (%5.3f) %6.2f MB/s %6.1f MB/s  %s \n",level,packed,ratio,400.0,2000.0,name.c_str());
        else {std::cerr<<clearLine;fprintf(stderr," |-%.17s%*s : %9zu ->\r",name.c_str(),std::max(0,17-int(name.size())),"",data.size());printf(" /-%-17.17s : %9zu -> %9zu (%5.3f), %5.1f MB/s\r =-%-17.17s : %9zu -> %9zu (%5.3f), %5.1f MB/s, %6.1f MB/s\r %d#\n",name.c_str(),data.size(),packed,ratio,400.0,name.c_str(),data.size(),packed,ratio,400.0,2000.0,level);}
