    if(o.display>=4)std::cerr<<"_POSIX_C_SOURCE defined: 200809L\n_POSIX_VERSION defined: 200809L\nPLATFORM_POSIX_VERSION defined: 200809L\n";
    if(o.recursive){std::vector<std::string> files;for(auto& f:o.files)collectFiles(f,files);o.files=std::move(files);}
    if(o.mode==Options::LIST){
        if(o.display<3)std::cout<<listHead;
        for(size_t i=0;i<o.files.size();++i){int r=listFile(o,o.files[i],int(i+1),int(o.files.size()));if(r)return r;}
        return 0;
    }
    if(o.mode==Options::BENCH)return benchmark(o);
    if(o.multiple)o.input=o.files.empty()?"stdin":o.files[0];
    if(o.input.empty())o.input="stdin";
    if(o.mode==Options::AUTO)o.mode=suffix(o.input,".lz4")?Options::DECOMPRESS:Options::COMPRESS;
    bool testing=o.mode==Options::TEST;
    if(testing){o.output="null";o.outputSet=true;o.force=true;o.remove=false;}
    if(stdinName(o.input)&&isatty(STDIN_FILENO)) {if(o.display>=1)std::cerr<<"refusing to read from a console\n";return 1;}
    if(!o.outputSet && (!o.multiple || o.files.empty())) {
        if(stdinName(o.input)){o.output="stdout";}
        else if(o.mode==Options::COMPRESS){o.output=o.input+".lz4";if(o.display>=2)std::cerr<<"Compressed filename will be : "<<o.output<<" \n";}
        else {
            if(!suffix(o.input,".lz4")){if(o.display>=1)std::cerr<<"Cannot determine an output filename \n";return incorrect(o);}
            o.output=o.input.substr(0,o.input.size()-4);if(o.display>=2)std::cerr<<"Decoding file "<<o.output<<" \n";
        }
    }
    if(stdoutName(o.output)&&isatty(STDOUT_FILENO)&&!o.forceStdout){if(o.display>=1)std::cerr<<"refusing to write to console without -c \n";return 1;}
