    if(o.mode==Options::COMPRESS && o.cfg.contentSize && stdinName(o.input) && o.display>=2)std::cerr<<"warning : --content-size cannot determine size when used with stdin\n";
    if((stdoutName(o.output)||o.multiple)&&o.display==2)o.display=1;
    Bytes dictionary;
    if(!o.dict.empty()) {
        FILE* f=inputFile(o,o.dict);
        if(!f){error(o,27,"Dictionary error : could not open dictionary file");return 27;}
        bool ok=readAll(f,dictionary);if(f!=stdin)fclose(f);
        if(!ok){error(o,28,"Dictionary error : could not read dictionary file");return 28;}
        if(dictionary.size()>65536)dictionary.erase(dictionary.begin(),dictionary.end()-65536);
    }
    int result=0;
    if(o.multiple&&!o.files.empty()) {
        for(const std::string& name:o.files){
            std::string out;
            if(o.outputSet)out="stdout";
            else if(o.mode==Options::COMPRESS)out=name+".lz4";
            else {
