        }
    }else result=o.mode==Options::COMPRESS?compressFile(o,o.input,o.output,dictionary):decompressFile(o,o.input,o.output,dictionary,testing);
    if(o.pause){std::cerr<<"Press enter to continue...\n";getchar();}
    return result;
}
