                    if(i+1==argc){if(o.display>=1)std::cerr<<"error: missing command argument \n";return 1;}
                    value=argv[++i];if(!value.empty()&&value[0]=='-'){if(o.display>=1)std::cerr<<"error: command cannot be separated from its argument by another command \n";return 1;}
                }else value=a.substr(10);
