                    case 'e':o.benchEnd=int(readNumber(a,j));break;
                    case 'i':o.benchSeconds=int(readNumber(a,j));if(o.display>=3)std::cerr<<"- test >= "<<o.benchSeconds<<" seconds per iteration - \n";break;
                    case 'D':
