static void collectFiles(const std::string& path,std::vector<std::string>& result){
    struct stat st;
    if(stat(path.c_str(),&st)!=0 || !S_ISDIR(st.st_mode)){result.push_back(path);return;}
    DIR* d=opendir(path.c_str());if(!d)return;
    while(dirent* e=readdir(d)) {
        std::string name=e->d_name;if(name=="."||name=="..")continue;
        std::string full=path+((!path.empty()&&path.back()=='/')?"":"/")+name;
        struct stat ls;if(lstat(full.c_str(),&ls)==0&&S_ISLNK(ls.st_mode))continue;
        collectFiles(full,result);
    }
    closedir(d);
}
static FILE* inputFile(const Options& o,const std::string& name) {
    if(stdinName(name))return stdin;
    struct stat st;
    if(stat(name.c_str(),&st)==0&&S_ISDIR(st.st_mode)) {if(o.display>=1)std::cerr<<"lz4: "<<name<<" is a directory -- ignored \n";return nullptr;}
    FILE* fp=fopen(name.c_str(),"rb");
    if(!fp&&o.display>=1)std::cerr<<name<<": "<<strerror(errno)<<" \n";
    return fp;
}
static bool readAll(FILE* f,Bytes& out) {
    uint8_t b[65536];size_t n;
    while((n=fread(b,1,sizeof b,f))!=0)out.insert(out.end(),b,b+n);
    return !ferror(f);
}
static FILE* outputFile(const Options& o,const std::string& name,const std::string& input) {
    if(stdoutName(name)) {
        if(o.display>=4)std::cerr<<"Using stdout for output \n";
        if(o.sparse==0&&o.display>=4)std::cerr<<"Sparse File Support automatically disabled on stdout ; to force-enable it, add --sparse command \n";
        return stdout;
    }
    std::string target=name=="null"?"/dev/null":name;
    struct stat st;
    if(!o.force && !nullName(name) && stat(target.c_str(),&st)==0) {
        if(o.display<=1 || stdinName(input)){
            std::cerr<<name<<" already exists; not overwritten  \n";return nullptr;
        }
        std::cerr<<name<<" already exists; do you want to overwrite (y/N) ? ";std::cerr.flush();
        int answer=getchar();
        if(answer!='y'&&answer!='Y'){std::cerr<<"    not overwritten  \n";return nullptr;}
    }
    FILE* f=fopen(target.c_str(),"wb");if(!f&&o.display>=1)std::cerr<<target<<": "<<strerror(errno)<<"\n";return f;
}
static void copyMetadata(const std::string& from,const std::string& to){
    struct stat s,t;
    if(stdinName(from)||stdoutName(to)||nullName(to))return;
    if(stat(from.c_str(),&s)!=0 || stat(to.c_str(),&t)!=0 || !S_ISREG(t.st_mode))return;
    chmod(to.c_str(),s.st_mode&07777);
    struct timespec times[2]={s.st_atim,s.st_mtim};utimensat(AT_FDCWD,to.c_str(),times,0);
}
static bool writeData(FILE* f,const Bytes& b,bool sparse){
    if(!sparse)return b.empty()||fwrite(b.data(),1,b.size(),f)==b.size();
    // Holes are only used for sizable runs, preserving the exact logical file.
    size_t p=0;bool hole=false;
    while(p<b.size()) {
        size_t end=std::min(b.size(),p+32768);
        bool zero=std::all_of(b.begin()+p,b.begin()+end,[](uint8_t c){return !c;});
        if(zero) {if(fseeko(f,off_t(end-p),SEEK_CUR)!=0)return false;hole=true;}
        else {if(fwrite(b.data()+p,1,end-p,f)!=end-p)return false;hole=false;}
        p=end;
    }
    if(hole&&!b.empty()) {if(fseeko(f,-1,SEEK_CUR)!=0||fputc(0,f)==EOF)return false;}
    return true;
}
static int compressFile(const Options& o,const std::string& input,const std::string& output,const Bytes& dict){
    if(o.display>=3) {
        if(o.threads>200)std::cerr<<"Requested "<<o.threads<<" threads too large => automatically reduced to 200 \n";
        else if(o.threads!=1)std::cerr<<"Using "<<(o.threads?o.threads:55)<<" threads for compression \n";
        if(o.cfg.legacy)std::cerr<<"! Generating LZ4 Legacy format (deprecated) ! \n";
    }
    FILE* in=inputFile(o,input);if(!in)return 1;
    FILE* out=outputFile(o,output,input);if(!out){if(in!=stdin)fclose(in);return 1;}
    Bytes data;
    bool ok=readAll(in,data);if(in!=stdin)fclose(in);
    if(!ok){error(o,21,"Read error : cannot read input file");if(out!=stdout)fclose(out);return 21;}
    auto cfg=o.cfg;if(stdinName(input))cfg.contentSize=false;
    if(o.display>=3 && o.cfg.contentSize && (stdinName(input)||data.empty()))std::cerr<<"Warning : cannot determine input content size \n";
    Bytes compressed=codec::compress(data,cfg,dict);
    ok=writeData(out,compressed,false);if(out!=stdout)fclose(out);
    if(!ok){error(o,20,"Write error : cannot write compressed block");return 20;}
    copyMetadata(input,output);
    double ratio=100.0*compressed.size()/std::max(size_t(1),data.size());
    if(o.display>=2){
        if(o.cfg.legacy){if(!data.empty())fprintf(stderr,"\rRead : %zu MiB   ==> inf%%   ",data.size()>>20);}
        else fprintf(stderr,"\rRead : %zu MiB   ==> %.2f%%   ",data.size()>>20,ratio);
