        fprintf(stderr,"Compressed %zu bytes into %zu bytes ==> %.2f%%%s\n",data.size(),compressed.size(),ratio,o.cfg.legacy?" ":"");
    }
    if(o.display>=3)fprintf(stderr,"Done in 0.00 s ==> %.2f MiB/s  (cpu load : 99%%)\n",data.size()/1048576.0/0.00005);
